<script setup lang="ts">import{formatCurrency,formatDate}from"~~/shared/format";definePageMeta({layout:"admin",middleware:"admin"});const{data,refresh}=await useFetch("/api/admin/orders");async function setStatus(id:string,status:string){await $fetch(`/api/admin/orders/${id}/status`,{method:"PATCH",body:{status,note:"Diperbarui admin"}});await refresh();}async function retry(id:string){await $fetch(`/api/admin/shipments/${id}/retry`,{method:"POST"});}useSeoMeta({title:"Admin Pesanan"});</script>
<template><div><AdminPageHeader title="Pesanan"/><div class="grid gap-3"><article v-for="order in data?.orders" :key="(order as any).id" class="surface grid gap-4 p-5 lg:grid-cols-[1fr_auto_auto]"><div><b>{{(order as any).order_number}}</b><p class="text-xs text-slate-500">{{(order as any).recipient_name}} · {{formatDate((order as any).created_at)}}</p><p class="mt-1 text-xs uppercase">{{(order as any).payment_status}} · {{(order as any).status}} · {{(order as any).awb_number||'AWB belum ada'}}</p></div><b>{{formatCurrency((order as any).total_amount)}}</b><div class="flex gap-2"><select class="field" :value="(order as any).status" @change="setStatus((order as any).id,($event.target as HTMLSelectElement).value)"><option value="paid">Paid</option><option value="processing">Processing</option><option value="fulfilled">Fulfilled</option><option value="cancelled">Cancelled</option></select><AppButton variant="secondary" @click="retry((order as any).id)">Retry BCE</AppButton></div></article></div></div></template>
